import {GameModel,ROOMS,validateSave} from './model.mjs';
import {Renderer} from './render.mjs';
import {Soundscape} from './audio.mjs';
const $=id=>document.getElementById(id),show=(id,on=true)=>$(id).classList.toggle('hidden',!on),SAVE_KEY='nocturne-eclipse-save-v1';
let stored=null,storageOK=true;try{stored=validateSave(JSON.parse(localStorage.getItem(SAVE_KEY)));}catch{storageOK=false;}
const audio=new Soundscape();try{audio.enabled=localStorage.getItem('nocturne-sound')!=='off';}catch{}
let model=new GameModel(),renderer,mode='title',helpReturn='title',toastTimeout,bannerTimeout,acc=0,last=0,hudTimer=0;
const keys={},pulses={},pointers=new Map();
function clearInputs(){for(const k of Object.keys(keys))delete keys[k];for(const k of Object.keys(pulses))delete pulses[k];pointers.clear();document.querySelectorAll('[data-action]').forEach(b=>b.classList.remove('held'));if(model)model.prev={};}
function input(){const out={...keys,...pulses};for(const action of pointers.values())out[action]=true;return out;}
function notify(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('visible'),3000);}
function save(){const data=model.saveData();try{localStorage.setItem(SAVE_KEY,JSON.stringify(data));stored=data;storageOK=true;}catch{storageOK=false;notify('このブラウザーでは保存できません');}}
function setMode(next){mode=next;clearInputs();acc=0;for(const id of ['title','pause','help','map','death','victory'])show(id,id===next);const inGame=!['title','help'].includes(next)||next==='help'&&helpReturn!=='title';show('hud',inGame);show('objective',next==='play');show('touch',next==='play');audio.paused=next!=='play';if(next==='title'){show('continue',!!stored);$('start').textContent=stored?'はじめから':'聖堂へ入る →';}if(next==='pause')$('saveStatus').textContent=storageOK?'燭台とエリア移動時に自動保存':'この環境では保存できません';}
function banner(room){$('bannerEnglish').textContent=room.en;$('bannerName').textContent=room.name;show('roomBanner',false);requestAnimationFrame(()=>show('roomBanner'));clearTimeout(bannerTimeout);bannerTimeout=setTimeout(()=>show('roomBanner',false),3200);}
async function begin(resume){await audio.start().catch(()=>{});model=new GameModel(resume?stored:null);renderer.lastRoom=-1;setMode('play');handleEvents();if(!resume)notify('二つの月印を探し、聖堂の封印を解こう');updateHUD();}
function handleEvents(){for(const e of model.drain()){switch(e.type){case'room':banner(e.room);audio.boss=false;break;case'save':save();break;case'toast':notify(e.text);break;case'sound':audio.play(e.name);break;case'shake':renderer.shake=Math.max(renderer.shake,e.amount);break;case'dead':setMode('death');audio.play('hurt');break;case'victory':save();$('resultStats').textContent=`探索 ${Math.floor(model.progress.time/60)}分 · 討伐 ${model.progress.kills}体 · ソウル ${model.progress.gold}`;setMode('victory');audio.play('rest');break;}}}
function updateHUD(){const p=model.player,r=model.room,pr=model.progress;$('hpbar').style.width=(p.hp/model.maxHp*100)+'%';$('hptext').textContent=Math.ceil(p.hp)+' / '+model.maxHp;$('mpbar').style.width=p.mp+'%';$('potions').textContent=p.potions;$('seals').textContent=(pr.seals.includes('tide')?'◆':'◇')+' '+(pr.seals.includes('bell')?'◆':'◇');$('gold').textContent='✦ '+pr.gold;$('level').textContent='Lv. '+pr.level;$('areaEnglish').textContent=r.en;$('areaName').textContent=r.name;$('objective').textContent=pr.bossDefeated?'夜明けの聖堂 — 残された宝物を探そう':pr.seals.length<2?'書庫と鐘楼の月印を探す　'+pr.seals.length+' / 2':'紅の礼拝堂の奥へ — 封印扉が開いた';$('mapDot').setAttribute('cx',[15,55,55,55,105][r.id]);$('mapDot').setAttribute('cy',[26,26,44,8,26][r.id]);show('interact',!!model.activeInteract&&mode==='play');if(model.activeInteract)$('interact').querySelector('span').textContent=model.activeInteract.label;
 const boss=model.enemies.find(e=>e.type==='boss'&&e.hp>0);show('bossHUD',!!boss&&model.bossActive&&mode==='play');if(boss)$('bossbar').style.width=Math.max(0,boss.hp/boss.maxHp*100)+'%';audio.boss=model.bossActive;
 document.querySelector('[data-action="magic"]').style.opacity=p.mp<25?.45:1;document.querySelector('[data-action="dash"]').style.opacity=p.dashCd>0?.5:1;
 // A small DOM mirror makes the canvas state accessible to assistive tools and QA.
 $('game').setAttribute('aria-label',`${r.name}。体力 ${Math.ceil(p.hp)}。月印 ${pr.seals.length}。位置 ${Math.round(p.x)}, ${Math.round(p.y)}。${mode==='play'?'探索中':mode}`);
}
function mapOpen(){setMode('map');$('mapRooms').replaceChildren();for(const r of ROOMS){const cell=document.createElement('button');cell.tabIndex=-1;const visited=model.progress.visited.includes(r.id);cell.className=(visited?'visited ':'')+(r.id===model.room.id?'current':'');cell.style.gridColumn=[1,2,2,2,3][r.id];cell.style.gridRow=[2,2,3,1,2][r.id];cell.textContent=(r.id===model.room.id?'◆ ':'')+(visited?r.name:'未踏の領域');const small=document.createElement('small');small.textContent=r.id===2?(model.progress.seals.includes('tide')?'潮の月印 ✓':'◇ 潮の月印'):r.id===3?(model.progress.seals.includes('bell')?'鐘の月印 ✓':'◇ 鐘の月印'):r.id===4?(model.sealed?'✧ 二つの月印が必要':'封印解除'):'燭台・保存';cell.append(small);$('mapRooms').append(cell);}}
$('start').onclick=()=>{if(stored){show('title',false);show('newGameConfirm');}else begin(false);};
// Restart confirmation stays in-game and never silently overwrites an existing journey.
const confirmPanel=document.createElement('section');confirmPanel.id='newGameConfirm';confirmPanel.className='panel hidden';confirmPanel.innerHTML='<div class="modal"><h2>新しい旅を始める</h2><p>現在の進行は、新しい旅の保存時に上書きされます。</p><button id="confirmNew" class="primary">はじめから遊ぶ</button><button id="cancelNew" class="secondary">今の旅を残す</button></div>';$('app').append(confirmPanel);$('confirmNew').onclick=()=>{show('newGameConfirm',false);begin(false);};$('cancelNew').onclick=()=>{show('newGameConfirm',false);setMode('title');};
$('continue').onclick=()=>begin(true);$('pauseButton').onclick=()=>setMode('pause');$('resume').onclick=()=>{audio.start().catch(()=>{});setMode('play');};$('backTitle').onclick=()=>{save();setMode('title');};$('victoryTitle').onclick=()=>{save();setMode('title');};$('retry').onclick=()=>{model.retry();setMode('play');handleEvents();};$('explore').onclick=()=>{model.state='play';setMode('play');};$('heal').onclick=()=>{if(mode==='play')model.heal();};$('mapButton').onclick=mapOpen;$('closeMap').onclick=()=>setMode('play');
function openHelp(from){helpReturn=from;setMode('help');}$('titleHelp').onclick=()=>openHelp('title');$('helpButton').onclick=()=>openHelp('pause');$('closeHelp').onclick=()=>setMode(helpReturn);
$('sound').textContent='サウンド '+(audio.enabled?'ON':'OFF');$('sound').onclick=()=>{audio.setEnabled(!audio.enabled);audio.start().catch(()=>{});$('sound').textContent='サウンド '+(audio.enabled?'ON':'OFF');try{localStorage.setItem('nocturne-sound',audio.enabled?'on':'off');}catch{}};
const keyMap={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',Space:'jump',KeyZ:'jump',KeyJ:'attack',KeyX:'attack',KeyK:'dash',ShiftLeft:'dash',ShiftRight:'dash',KeyL:'magic',KeyC:'magic',ArrowUp:'interact',KeyW:'interact',KeyE:'interact',KeyH:'heal'};
window.addEventListener('keydown',e=>{if(e.code==='Escape'){e.preventDefault();if(mode==='play')setMode('pause');else if(['pause','map'].includes(mode))setMode('play');return;}if(e.code==='KeyM'&&!e.repeat&&mode==='play'){mapOpen();return;}const action=keyMap[e.code];if(action){e.preventDefault();if(mode==='play'){keys[action]=true;if(!e.repeat&&!['left','right'].includes(action))pulses[action]=true;}}},{passive:false});window.addEventListener('keyup',e=>{const action=keyMap[e.code];if(action){e.preventDefault();keys[action]=false;}},{passive:false});
for(const b of document.querySelectorAll('[data-action]')){b.addEventListener('pointerdown',e=>{if(mode!=='play')return;e.preventDefault();b.setPointerCapture(e.pointerId);pointers.set(e.pointerId,b.dataset.action);if(!['left','right'].includes(b.dataset.action))pulses[b.dataset.action]=true;b.classList.add('held');audio.start().catch(()=>{});},{passive:false});const release=e=>{pointers.delete(e.pointerId);if(![...pointers.values()].includes(b.dataset.action))b.classList.remove('held');};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);b.addEventListener('contextmenu',e=>e.preventDefault());}
window.addEventListener('blur',clearInputs);document.addEventListener('visibilitychange',()=>{clearInputs();if(document.hidden&&mode==='play'){setMode('pause');save();}last=performance.now();acc=0;});window.addEventListener('pagehide',()=>{if(mode!=='title')save();});window.addEventListener('resize',()=>renderer?.resize());window.visualViewport?.addEventListener('resize',()=>renderer?.resize());for(const name of ['gesturestart','gesturechange','gestureend','contextmenu'])document.addEventListener(name,e=>e.preventDefault(),{passive:false});document.addEventListener('dblclick',e=>e.preventDefault(),{passive:false});
function frame(now){const dt=Math.min((now-last)/1000||0,.1);last=now;if(mode==='play'){acc+=dt;let steps=0;while(acc>=1/60&&steps++<6){model.update(1/60,input());for(const k of Object.keys(pulses))delete pulses[k];acc-=1/60;handleEvents();if(mode!=='play')break;}}else if(mode==='title'){model.player.anim+=dt;}renderer.draw(model,dt,mode==='title');hudTimer+=dt;if(hudTimer>.1){updateHUD();hudTimer=0;}requestAnimationFrame(frame);}
async function boot(){const names=['cathedral','crypt','belfry','hero','enemies','props'],assets={};let completed=0;await Promise.all(names.map(name=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{assets[name]=im;completed++;$('loadbar').style.width=(completed/7*100)+'%';resolve();};im.onerror=()=>reject(new Error(name+' の画像を読み込めませんでした'));im.src='./assets/'+name+'.webp';})));const res=await fetch('./assets/atlas.json');if(!res.ok)throw new Error('アニメーションデータを読み込めませんでした');const atlas=await res.json();renderer=new Renderer($('game'),assets,atlas);$('loadbar').style.width='100%';show('loading',false);model.drain();setMode('title');last=performance.now();requestAnimationFrame(frame);if('serviceWorker'in navigator&&location.hostname!=='terminal.local')navigator.serviceWorker.register('./sw.js').catch(()=>{});}
boot().catch(e=>{show('loading',false);show('fatal');$('fatal').textContent='読み込みを完了できませんでした。\n'+e.message+'\n通信を確認してページを再読み込みしてください。';});
